{"command": "cd /home/zhaodan/work/NodeJsProjects/agent-hub-web && python3 - <<'PY'
from pathlib import Path
p = Path('src/api/mock/db.ts')
text = p.read_text()
marker = "  getSystemInfo(): SystemInfo {"
