    const agent: Agent = {
      id: crypto.randomUUID(),
      slug: slug || `agent-${this.agents.length + 1}`,
      name,
      description: `从 ${body.url} 注册的远程 Agent`,
      url: body.url,
      protocol_version: '1.0',
      skills: [{ id: `${slug}_default`, name: '默认技能' }],
