    { message },
    {
      signal,
      onEvent,
      onError: (error) => {
        throw error
      },
    },
    { frameDelay },
  )
}'''
new = '''function runStream(
  message: string,
  onEvent: (event: ChatEventName, data: unknown) => void,
  signal: AbortSignal,
  frameDelay = 0,
  extra: Record<string, unknown> = {},
): Promise<void> {
  return mockChatStream(
    { message, ...extra },
    {
      signal,
      onEvent,
      onError: (error) => {
        throw error
      },
    },
    { frameDelay },
