function openAdd(): void {
  addForm.name = ''
  addForm.url = ''
  addForm.transport = 'streamable_http'
  addForm.secretRef = ''
  addForm.autoInject = false
  addOpen.value = true
}

async function submitAdd(): Promise<void> {
  if (adding.value) return
  const name = addForm.name.trim()
  const url = addForm.url.trim()
  if (!name || !url) {
    ElMessage.warning('名称与 URL 均为必填')
    return
  }
  const secretRef = addForm.secretRef.trim()
  adding.value = true
  try {
    await mcpApi.createServer({
      name,
      url,
      transport: addForm.transport,
      auth: secretRef ? { type: 'api_key', secret_ref: secretRef } : { type: 'none' },
      auto_inject: addForm.autoInject,
    })
    addOpen.value = false
    capabilities.invalidate()
    await load()
    ElMessage.success('已添加服务器')
  } catch (cause) {
    ElMessage.error(cause instanceof Error ? cause.message : '添加失败')
  } finally {
    adding.value = false
  }
}

