const BASE='http://127.0.0.1:8000/api/v1'
const login=await fetch(BASE+'/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:'dev@example.com',password:'dev-password-123'})})
const {access_token}=await login.json()
const H={Authorization:`Bearer ${access_token}`}
const J={...H,'Content-Type':'application/json'}
const skill=await (await fetch(BASE+'/skills',{method:'POST',headers:J,body:JSON.stringify({name:'Smoke Chat Skill',description:'smoke',content:'# Smoke\n\n先给结论。'})})).json()
const form=new FormData(); form.append('file',new Blob(['订单,金额\nA,10\n'],{type:'text/csv'}),'chat.csv')
const att=await (await fetch(BASE+'/attachments',{method:'POST',headers:H,body:form})).json()
const payload={message:'用技能回答并记住：以后先给结论。',skills:[skill.id],attachments:[att.id],client_message_id:'smoke-'+Date.now()}
const res=await fetch(BASE+'/chat/stream',{method:'POST',headers:{...J,Accept:'text/event-stream'},body:JSON.stringify(payload)})
console.log('stream',res.status,res.headers.get('content-type'),res.headers.get('x-run-id'))
const reader=res.body.getReader(); const dec=new TextDecoder(); let buf=''; const events=[]
while(true){const {done,value}=await reader.read(); if(done) break; buf+=dec.decode(value,{stream:true}); let i; while((i=buf.indexOf('\n\n'))>=0){const frame=buf.slice(0,i); buf=buf.slice(i+2); let ev='',data=''; for(const line of frame.split('\n')){if(line.startsWith('event:'))ev=line.slice(6).trim(); else if(line.startsWith('data:'))data+=line.slice(5).trim();} if(ev) events.push([ev,data]);}}
console.log('events:',events.map(e=>e[0]).join(', '))
for(const [ev,data] of events){ if(['skill.activated','memory.saved','tool.start','tool.result','message.done','error','notice'].includes(ev)) console.log(ev, data.slice(0,300)); }
console.log('conversation',events.find(e=>e[0]==='run.started')?.[1]?.slice(0,200))
