    { id: 'summarize', name: '摘要', description: '返回摘要', tags: ['test'] },
  ],
}
const tasks = new Map()

function send(res, status, body, contentType = 'application/json') {
  res.writeHead(status, { 'content-type': contentType })
  res.end(typeof body === 'string' ? body : JSON.stringify(body))
}

createServer(async (req, res) => {
  if (req.method === 'GET' && (req.url === '/.well-known/agent-card.json' || req.url === '/.well-known/agent.json')) {
    return send(res, 200, card)
  }
  if (req.method === 'POST' && req.url === '/') {
    let raw = ''
    for await (const chunk of req) raw += chunk
    let payload
    try { payload = JSON.parse(raw) } catch { return send(res, 400, { error: 'bad json' }) }
    const id = payload.id
    const method = payload.method
    const params = payload.params ?? {}
    if (method === 'message/send') {
      const text = (params.message?.parts ?? []).map(p => p.text ?? '').join('\n')
      const taskId = `task-${Date.now()}-${Math.floor(Math.random()*1000)}`
      const task = {
        id: taskId,
        contextId: params.message?.contextId ?? `ctx-${Date.now()}`,
        status: { state: 'completed', message: { role: 'agent', parts: [{ kind: 'text', text: `本地 Agent 已处理：${text}` }] } },
        artifacts: [{ artifactId: 'a1', name: 'result', parts: [{ kind: 'text', text: `echo: ${text}` }] }],
      }
      tasks.set(taskId, task)
      return send(res, 200, { jsonrpc: '2.0', id, result: task })
    }
    if (method === 'tasks/get') {
      const task = tasks.get(params.id) ?? { id: params.id, status: { state: 'completed' }, artifacts: [] }
      return send(res, 200, { jsonrpc: '2.0', id, result: task })
    }
    if (method === 'tasks/cancel') {
      const task = tasks.get(params.id) ?? { id: params.id }
      task.status = { state: 'canceled' }
      return send(res, 200, { jsonrpc: '2.0', id, result: task })
    }
    return send(res, 200, { jsonrpc: '2.0', id, error: { code: -32601, message: 'unknown method' } })
  }
  return send(res, 404, { error: 'not found' })
}).listen(PORT, '127.0.0.1', () => console.log(`fake a2a on ${BASE}`))
