{"command": "cd /home/zhaodan/work/NodeJsProjects/agent-hub-web && node --input-type=module - <<'JS'
const BASE='http://127.0.0.1:8000/api/v1'
const login=await fetch(BASE+'/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:'dev@example.com',password:'dev-password-123'})})
const {access_token}=await login.json(); const H={Authorization:`Bearer ${access_token}`,'Content-Type':'application/json'}
const agent=await (await fetch(BASE+'/agents',{method:'POST',headers:H,body:JSON.stringify({url:'http://127.0.0.1:9101',slug:'local-echo'})})).json()
console.log('agent',agent.id)
const payload={message:'请调用远程智能体 local-echo，把这句话复述一下：「M2 冒烟测试」。必须使用 send_message 工具，agent=local-echo。',client_message_id:'m2-'+Date.now()}
const res=await fetch(BASE+'/chat/stream',{method:'POST',headers:{...H,Accept:'text/event-stream'},body:JSON.stringify(payload)})
console.log('stream',res.status,res.headers.get('x-run-id'))
const reader=res.body.getReader(); const dec=new TextDecoder(); let buf=''; const events=[]
while(true){const {done,value}=await reader.read(); if(done) break; buf+=dec.decode(value,{stream:true}); let i; while((i=buf.indexOf('\n\n'))>=0){const f=buf.slice(0,i);buf=buf.slice(i+2);let ev='',data='';for(const line of f.split('\n')){if(line.startsWith('event:'))ev=line.slice(6).trim();else if(line.startsWith('data:'))data+=line.slice(5).trim();}if(ev)events.push([ev,data]);}}
console.log('events',events.map(e=>e[0]).join(', '))
for(const [ev,data] of events){if(['tool.start','tool.result','a2a.task','a2a.artifact','a2a.input_required','a2a.auth_required','error','notice','message.done'].includes(ev))console.log(ev,data.slice(0,400))}
// tasks
const tasks=await (await fetch(BASE+'/tasks',{headers:H})).json(); console.log('tasks',JSON.stringify(tasks).slice(0,1000))
