const reader = res.body.getReader(); const dec = new TextDecoder(); let buf = ''; const events = []
const donePromise = (async () => { while (true) { const { done, value } = await reader.read(); if (done) break; buf += dec.decode(value, { stream: true }); let i; while ((i = buf.indexOf('\n\n')) >= 0) { const f = buf.slice(0, i); buf = buf.slice(i + 2); let ev = '', data = ''; for (const line of f.split('\n')) { if (line.startsWith('event:')) ev = line.slice(6).trim(); else if (line.startsWith('data:')) data += line.slice(5).trim() } if (ev) { events.push([ev, data]); if (ev === 'a2a.auth_required') console.log('AUTH_EVENT', data.slice(0, 300)) } } } })()
let task
