console.log('auth_request', JSON.stringify(detail.auth_request), 'actions', JSON.stringify(detail.available_actions))
const rr = await fetch(BASE + '/tasks/' + task.id + '/authorize', { method: 'POST', headers: H, body: JSON.stringify({ scopes: ['repo:read'], note: '已授权' }) })
console.log('authorize', rr.status, (await rr.text()).slice(0, 200))
await donePromise
const final = await (await fetch(BASE + '/tasks/' + task.id, { headers: H })).json()
console.log('final', final.state)
console.log('events', [...new Set(events.map((e) => e[0]))].join(','))
await fetch(BASE + '/agents/' + agent.id, { method: 'DELETE', headers: H })
